import '../plugins/plugin.dart';
import 'fuzzy_matcher.dart';
import '../skills/skills.dart';
import 'prompt_templates.dart';
import 'tui_repl.dart';

/// Builds the slash-menu items for [prefix]: builtin commands (matched on
/// name or description), plugin commands (name only), prompt templates, and
/// user-invocable skills (name or description). A skill's key carries a
/// trailing space so accepting it leaves the cursor ready for args.
List<MenuItem> buildSlashMenuItems(
  String prefix, {
  required Map<String, String> slashCommands,
  required Map<String, SlashCommand> pluginSlashCommands,
  Map<String, String> pluginSlashDescriptions = const {},
  Map<String, SlashCommand> extSlashCommands = const {},
  required List<PromptTemplate> templates,
  List<Skill> skills = const [],
}) {
  final lower = prefix.toLowerCase();
  // Plugin commands shadow the same-named ext commands: one row per name.
  final extOnly = Map.of(extSlashCommands)
    ..removeWhere((key, _) => pluginSlashCommands.containsKey(key));
  return [
    ..._builtinMenuItems(slashCommands, lower),
    ..._pluginMenuItems(pluginSlashCommands, lower, pluginSlashDescriptions),
    ..._pluginMenuItems(extOnly, lower, const {}),
    ..._templateMenuItems(templates, lower),
    ..._skillMenuItems(skills, lower),
  ];
}

/// Subsequence fallback for the composer's fuzzy overlay (issue #275):
/// a candidate survives the substring filter when its key fuzzy-matches
/// the prefix, so '/e' still surfaces /help and /model.
bool _fuzzyKeyHit(String key, String prefix) =>
    prefix.isEmpty || scoreFuzzy(key, prefix) != null;

List<MenuItem> _builtinMenuItems(
  Map<String, String> slashCommands,
  String lower,
) {
  final items = <MenuItem>[];
  for (final entry in slashCommands.entries) {
    if (entry.key.toLowerCase().contains(lower) ||
        entry.value.toLowerCase().contains(lower) ||
        _fuzzyKeyHit(entry.key, lower)) {
      items.add(
        MenuItem(
          key: entry.key,
          label: entry.key,
          description: entry.value,
          group: 'commands',
        ),
      );
    }
  }
  return items;
}

List<MenuItem> _pluginMenuItems(
  Map<String, SlashCommand> pluginSlashCommands,
  String lower,
  Map<String, String> descriptions,
) {
  final items = <MenuItem>[];
  for (final entry in pluginSlashCommands.entries) {
    if (entry.key.toLowerCase().contains(lower) ||
        _fuzzyKeyHit(entry.key, lower)) {
      items.add(
        MenuItem(
          key: entry.key,
          label: entry.key,
          description: descriptions[entry.key] ?? '',
          group: 'commands',
        ),
      );
    }
  }
  return items;
}

List<MenuItem> _templateMenuItems(
  List<PromptTemplate> templates,
  String lower,
) {
  final items = <MenuItem>[];
  for (final t in templates) {
    final name = '/${t.name}';
    if (name.toLowerCase().contains(lower) || _fuzzyKeyHit(name, lower)) {
      items.add(
        MenuItem(
          key: name,
          label: name,
          description: t.argumentHint ?? '',
          group: 'commands',
        ),
      );
    }
  }
  return items;
}

List<MenuItem> _skillMenuItems(List<Skill> skills, String lower) {
  // Normalize the typed prefix to the bare skill-name fragment: '/goal',
  // 'goal', and '/skill:goal' all must offer '/create-goal' — matching the
  // raw prefix against '/<name>' breaks on the embedded slash (user report:
  // typing /goal showed no suggestion).
  var needle = lower.startsWith('/') ? lower.substring(1) : lower;
  if (needle.startsWith('skill:')) {
    needle = needle.substring('skill:'.length);
  }
  final items = <MenuItem>[];
  for (final skill in userInvocableSkills(skills)) {
    final hint = skill.manifest.argumentHint;
    // First-party badge (issue #1151 AC5): package-shipped skills are
    // greppable in completion so users can tell them from project skills.
    final badge = skill.source == SkillSource.builtin ? ' (builtin)' : '';
    final description = hint == null || hint.isEmpty
        ? '${skill.description}$badge'
        : '${skill.description}$badge $hint';
    if (skill.name.toLowerCase().contains(needle) ||
        skill.description.toLowerCase().contains(needle) ||
        _fuzzyKeyHit('/${skill.name}', needle)) {
      items.add(
        MenuItem(
          key: '/skill:${skill.name} ',
          label: '/${skill.name}',
          description: description,
          group: 'skills',
        ),
      );
    }
  }
  return items;
}

/// The skills offered by the slash menu / line-mode menu: explicit
/// invocation requires the manifest's `user-invocable` (default true).
Iterable<Skill> userInvocableSkills(List<Skill> skills) =>
    skills.where((s) => s.userInvocable);

/// The builtin slash commands, in help/menu order.
const builtinSlashCommands = <String, String>{
  '/exit': 'quit',
  '/reset': 'start a new session',
  '/compact': 'summarize history to free context',
  '/stats': 'show token and cost totals',
  '/tasks': '[cancel <id>] — list background agents',
  '/queue': '[clear] — queued follow-up messages (strip above the input)',
  '/memory': '[maintain] — memory stats or run consolidation',
  '/power': 'show sleep prevention (caffeinate) level and state',
  '/quota': '[refresh] — provider quota: used/limit, reset, updated',
  '/timer':
      '[<duration|epoch-ms>|clear] — session deadline countdown '
      '(25m, 90s, 1h30m)',
  '/redact': '[on|off|block on|block off|stats|layers] — secret redaction',
  '/a2a': 'show A2A remote agent servers status',
  '/skills': 'list discovered skills (invoke with /skill:<name>)',
  '/ext': '[list|enable|disable|audit|remove|update|reload] — JS extensions',
  '/jsr':
      '[widget:test|widget:screenshot] — jsr widget CLI pass-through '
      '(js_widget_runtime)',
  '/agents':
      '[types|<id>|open <id>] — agents hub: fleet tree, transcript, '
      'observe, open session',
  '/mail': '[<id>] — deferred messages (btw panels) and their state',
  '/reply': '<id|agent|mailbox> <text> — answer a panel or agent',
  '/restart':
      'abort a stalled run and re-run its saved steering as a fresh turn',
  '/model': '<provider/model> — select model (opens selector)',
  '/models': '[filter] | config | set <slot> <model> [baseUrl] | remove <slot>',
  '/model-edit':
      '[contextWindow|maxTokens <n>] — show or override token limits',
  '/provider':
      '[name] [baseUrl] [token] | add | custom — switch or add provider',
  '/providers': 'provider queue editor (issue #418)',
  // /provider-edit removed — edit/delete is now inline in /provider picker.
  '/mode': '[name] — show or switch the active mode',
  '/theme': '[name|reset] — switch TUI theme (bare opens picker)',
  '/session': '[name] — show current or switch/create a named session',
  '/session-new': '<name> — create a new named session',
  '/sessions': 'list all sessions across workspaces',
  '/import':
      'import omp/claude sessions recorded for this folder into fa',
  '/resume': 'switch to the most recent session',
  '/rename-session': '<name> — rename the current session',
  '/trajectory': '[view|cost|tail|inspect <n>] — session trajectory ledger',
  '/usage': '[rebuild] — session token-usage ledger (usage.json)',
  '/approval': '[mode] — show or set tool approval',
  '/settings': '— settings hub: provider, model, approval, keys, MCP',
  '/update': '— check for updates, restart fa (same session)',
  '/allow': '[tool] — always-allow a tool (or list them)',
  '/mcp': '[list|reload] — show MCP servers or reload config',
  '/mouse': '[on|off] — TUI mouse capture: wheel + click hit-regions',
  '/terminal-setup':
      'Shift+Enter newline support per terminal (Ctrl+O always works)',
  '/tools':
      '[enable|disable <id> [global|project|session]|reload] — tool '
      'availability',
  '/code': 'switch to coding mode',
  '/architect': 'switch to architect mode',
  '/review': 'switch to review mode',
  '/help': '[filter] — command summary (/help hotkeys: key table)',
  '!': '<command> — run a shell command directly',
};

/// The `/help` listing as styled lines: the (optionally filtered) builtin
/// commands, then — for the full listing only — plugin commands, prompt
/// templates, skills, and the steer hint.
List<String> helpLines({
  String filter = '',
  required Map<String, SlashCommand> pluginSlashCommands,
  Map<String, SlashCommand> extSlashCommands = const {},
  required List<PromptTemplate> templates,
  required TuiStyle style,
  List<Skill> skills = const [],
}) {
  final lower = filter.toLowerCase();
  final entries = builtinSlashCommands.entries
      .where(
        (e) =>
            e.key.toLowerCase().contains(lower) ||
            e.value.toLowerCase().contains(lower) ||
            _fuzzyKeyHit(e.key, lower),
      )
      .toList();
  if (entries.isEmpty) return [_helpEmptyLine(filter)];
  final lines = [
    style.bold(filter.isEmpty ? '[Commands]' : '[Commands matching "$filter"]'),
    for (final entry in entries)
      '  ${style.cyan(entry.key.padRight(18))} ${entry.value}',
  ];
  // Plugin commands, prompt templates, skills, and the steer hint are part
  // of the full listing only, never of a filtered one.
  if (filter.isNotEmpty) return lines;
  return [
    ...lines,
    ..._helpExtrasLines(
      pluginSlashCommands,
      extSlashCommands,
      templates,
      style,
      skills,
    ),
  ];
}

/// The no-match line for a filtered `/help`.
String _helpEmptyLine(String filter) => filter.isNotEmpty
    ? 'unknown command: /$filter (try /help)'
    : 'no commands match "$filter"';

/// The full-listing appendix: plugin commands, prompt templates, skills,
/// and the steer hint.
List<String> _helpExtrasLines(
  Map<String, SlashCommand> pluginSlashCommands,
  Map<String, SlashCommand> extSlashCommands,
  List<PromptTemplate> templates,
  TuiStyle style,
  List<Skill> skills,
) {
  return [
    if (pluginSlashCommands.isNotEmpty) ...[
      '',
      style.bold('[Plugin commands]'),
      for (final entry in pluginSlashCommands.entries)
        '  ${style.cyan(entry.key)}',
      if (extSlashCommands.isNotEmpty) ...[
        '',
        style.bold('[Extension commands]'),
        for (final entry in extSlashCommands.entries)
          '  ${style.cyan(entry.key)}',
      ],
    ],
    if (templates.isNotEmpty) ...[
      '',
      style.bold('[Prompt templates]'),
      for (final t in templates)
        '  ${style.cyan('/${t.name}')} ${t.argumentHint ?? ''}',
    ],
    if (skills.isNotEmpty) ...[
      '',
      style.bold('[Skills]'),
      for (final s in skills) '  ${style.cyan('/${s.name}')} ${s.description}',
    ],
    '',
    style.dim('While a run streams, type to steer the agent; Ctrl-C aborts.'),
  ];
}

/// The numbered entries of the line-mode menu: builtin commands, then
/// user-invocable skills (a skill choice resolves to `/skill:<name>`).
List<MenuItem> lineModeMenuEntries(List<Skill> skills) {
  return [
    for (final entry in builtinSlashCommands.entries)
      MenuItem(key: entry.key, label: entry.key, description: entry.value),
    for (final skill in userInvocableSkills(skills))
      MenuItem(
        key: '/skill:${skill.name}',
        label: '/${skill.name}',
        description: skill.description,
      ),
  ];
}

/// The numbered command list of the line-mode menu, as styled lines.
List<String> lineModeMenuLines(
  TuiStyle style, {
  List<Skill> skills = const [],
}) {
  final entries = lineModeMenuEntries(skills);
  return [
    '',
    style.bold('[Commands]'),
    for (var i = 0; i < entries.length; i++)
      '  ${i + 1}) ${style.cyan(entries[i].label)} ${entries[i].description}',
    '',
  ];
}

/// Resolves a line-mode menu answer: a 1-based number over the builtin
/// commands + skills, or a command/skill name with or without the leading
/// slash. Null when neither matches.
String? resolveLineModeMenuChoice(String trimmed, List<Skill> skills) {
  final entries = lineModeMenuEntries(skills);
  // Numeric choice.
  final index = int.tryParse(trimmed);
  if (index != null && index >= 1 && index <= entries.length) {
    return entries[index - 1].key;
  }
  // Name choice; accept with or without leading slash. Builtins first.
  final name = trimmed.startsWith('/') ? trimmed : '/$trimmed';
  if (builtinSlashCommands.containsKey(name)) return name;
  for (final skill in userInvocableSkills(skills)) {
    if ('/${skill.name}'.toLowerCase() == name.toLowerCase()) {
      return '/skill:${skill.name}';
    }
  }
  return null;
}

// The slash-menu key cluster (file-length gate, PR #831): the
// FaTuiModel menu-mode key handlers extracted verbatim from fa_tui.dart.
// Same library via `part`, so the private members they touch stay
// private; zero API surface change.

part of 'fa_tui.dart';

extension FaTuiModelSlashMenu on FaTuiModel {
  /// Slash/menu mode: arrows navigate, enter/tab accept, esc closes, and
  /// typing keeps editing the input so `/models` can be typed in full.
  (Model, Cmd?) _handleSlashMenuKey(KeyMsg msg) {
    return _handleSlashMenuNavKey(msg) ??
        _handleSlashMenuAcceptKey(msg) ??
        _handleSlashMenuEditKey(msg);
  }

  /// Path-completion overlay keys: Tab accepts, arrows navigate, esc
  /// closes; everything else falls through (Enter SUBMITS, editing edits).
  (Model, Cmd?)? _handlePathMenuKey(KeyMsg msg) {
    switch (msg.key) {
      case 'tab':
        return _acceptSlashMenuItem();
      case 'esc':
        return (copyWith(menuOpen: false, menuTokenStart: -1), null);
      case 'up':
      case 'down':
        return _handleSlashMenuNavKey(msg);
      default:
        return null;
    }
  }

  /// Slash-menu navigation keys (esc/up/down); null when the key belongs to
  /// the accept or edit clusters.
  (Model, Cmd?)? _handleSlashMenuNavKey(KeyMsg msg) {
    switch (msg.key) {
      case 'esc':
        return (copyWith(menuOpen: false, menuTokenStart: -1), null);
      case 'up':
        return (
          copyWith(menuSelected: menuSelected > 0 ? menuSelected - 1 : 0),
          null,
        );
      case 'down':
        return (
          copyWith(
            menuSelected: menuSelected < menuItems.length - 1
                ? menuSelected + 1
                : menuSelected,
          ),
          null,
        );
      default:
        return null;
    }
  }

  /// Slash-menu accept keys (enter/tab); null for every other key.
  (Model, Cmd?)? _handleSlashMenuAcceptKey(KeyMsg msg) {
    switch (msg.key) {
      case 'enter':
      case 'tab':
        return _acceptSlashMenuItem();
      default:
        return null;
    }
  }

  /// Slash-menu edit keys: backspace and typed characters keep editing the
  /// input so `/models` can be typed in full.
  (Model, Cmd?) _handleSlashMenuEditKey(KeyMsg msg) {
    switch (msg.key) {
      case 'backspace':
        if (cursor > 0 && inputText.isNotEmpty) {
          return (
            _updateMenuForInput(copyWith(editor: editor.backspace())),
            null,
          );
        }
        return (this, null);
      default:
        final text = msg.keyEvent.text;
        if (text.isNotEmpty && text.length == 1) {
          return (
            _updateMenuForInput(copyWith(editor: editor.insert(text))),
            null,
          );
        }
        return (this, null);
    }
  }

  /// Slash-menu accept (enter/tab): fills the input with the picked command,
  /// or switches into the models picker, or submits picker-opening commands
  /// (/sessions, /mode, /approval) immediately.
  (Model, Cmd?) _acceptSlashMenuItem() {
    if (menuItems.isEmpty) return (this, null);
    final item = menuItems[menuSelected];
    if (item.key == '/model' || item.key == '/models') {
      return (
        copyWith(
          menuModelMode: true,
          menuItems: callbacks.buildModelMenu('', termWidth),
          menuSelected: 0,
          modelFilter: '',
          pickerId: 'models',
          pickerTitle: '',
        ),
        null,
      );
    }
    // Commands that open a host-side picker (/sessions, /mode,
    // /approval) submit immediately instead of filling the input.
    if (callbacks.opensPicker?.call(item.key) ?? false) {
      return (
        copyWith(menuOpen: false, inputText: '', cursor: 0, pickerId: ''),
        () async {
          await callbacks.onSubmit(item.key, images: const []);
          return null;
        },
      );
    }
    // Token splice (issue #275): replace just the completed token — an
    // `@`-fragment or a shell word after '!' — with the chosen path plus a
    // trailing space that ends the token. Slash commands (tokenStart == 0,
    // line-start) keep the legacy whole-input replace below.
    if (menuTokenStart > 0) {
      final head = inputText.substring(0, menuTokenStart);
      final tail = inputText.substring(
        cursor.clamp(menuTokenStart, inputText.length),
      );
      final inserted = '${item.key} ';
      return (
        copyWith(
          inputText: head + inserted + tail,
          cursor: menuTokenStart + inserted.length,
          menuOpen: false,
          menuTokenStart: -1,
        ),
        null,
      );
    }
    return (
      copyWith(
        inputText: item.key,
        cursor: item.key.length,
        menuOpen: false,
        menuTokenStart: -1,
      ),
      null,
    );
  }
}

part of 'fa_tui.dart';

/// FaTuiModel's composer layout — split out of `fa_tui.dart` to keep it
/// under the repo's 2800-line size gate. Same library (a `part of`), so
/// the extension sees the model's private members (issue #467).

extension _TuiComposerLayout on FaTuiModel {
  /// The band composer attachment (#806): the host supplies a snapshot
  /// builder + the status-line engine unless the `tui.classic` kill
  /// switch pinned the legacy chrome.
  bool get _bandAttached =>
      callbacks.statusSnapshot != null && callbacks.statusLineEngine != null;

  /// The input block's height in PHYSICAL rows: the text soft-wraps to the
  /// terminal width, so a long single line occupies several rows. All
  /// layout math (viewport height, cursor homing) must use this count —
  /// the raw `\n` count lies once a line wraps.
  int get _inputLineCount => _wrappedInput().$1.length;

  /// Truncates [text] to [maxWidth] (default: the terminal width) with an
  /// ellipsis. Every chrome row (status, menu items) must fit on one
  /// terminal row: a soft-wrapped chrome line desyncs the renderer's row
  /// math and smears the frame on every repaint.
  /// Truncates [text] to the terminal width in terminal cells (not UTF-16
  /// units) so wide characters cannot push chrome rows past the width.
  String _fitWidth(String text, [int? maxWidth]) =>
      tuiFitWidth(text, maxWidth ?? termWidth);

  /// The per-frame layout plan (issue #496): how many rows of every
  /// optional section the frame paints, plus the history window. ONE
  /// computation serves both the budget getter and the painters, so the
  /// painted frame can never disagree with the row math — the old code
  /// floored the viewport at 0 while the pin/board/queue chrome kept
  /// painting unconditionally, the frame overran the physical screen, the
  /// real composer rows never reached the glass and stale rows below the
  /// painted region kept the submitted text + cursor visible (the owner's
  /// "echo duplicates into the input row").
  ///
  /// When the mandatory chrome (progress, busy row, menu, prompt, input
  /// frame, status, input rows) alone would not leave room, optional
  /// sections yield, most dispensable first: job board, waiting rows,
  /// scheduled row, attachment chips, queue block, pinned echo. One
  /// history row is reserved ahead of the optional chrome whenever the
  /// transcript is non-empty: the live edge (the sent echo / newest answer
  /// line) must stay on screen even on a squeezed frame.
  /// The mandatory fixed-chrome row count for the current frame shape.
  /// Band composer (#806): the top band replaces the composer's top
  /// rule, bottom rule and status footer — the chrome below the scroll
  /// indicator shrinks from three rows to one (the band) and the freed
  /// rows go to history. Prompt mode keeps the legacy layout (the
  /// prompt zone replaces the composer; its footer stays).
  int get _mandatoryChromeRows {
    const legacyMandatory =
        1 /* progress indicator */ +
        2 /* input frame rules */ +
        1 /* status row */;
    const bandMandatory =
        1 /* progress indicator */ +
        1 /* top status band (always owns its row — omp verticalChrome: 1) */;
    return _bandAttached && prompt == null ? bandMandatory : legacyMandatory;
  }

  /// The optional sections' wanted row counts, in consumption order
  /// (issue #496): subagents, board, waiting, scheduled, chips, queue,
  /// sticky. The subagent board (gh-1415) sits in FRONT of the job board:
  /// the card's rows are the region the whole frame exists to show.
  (int, int, int, int, int, int, int) _optionalSectionWants(int width) {
    final subagentsWanted = subagentBoardRows.length;
    final boardWanted = jobBoardLines.length;
    final waitingWanted = _waitingRowLines().length;
    final scheduledWanted = scheduledCount > 0 ? 1 : 0;
    final chipsWanted = attachments.isEmpty ? 0 : attachments.length + 1;
    final queueWanted = queue.isEmpty ? 0 : queue.length + 2;
    final stickyWanted = _stickyArmed ? _formattedStickyRows(width).length : 0;
    return (
      subagentsWanted,
      boardWanted,
      waitingWanted,
      scheduledWanted,
      chipsWanted,
      queueWanted,
      stickyWanted,
    );
  }

  /// The queue block's progressive yield: the hint row drops first, then
  /// the OLDEST queued rows — the `queued (N)` header is the "your typing
  /// is not lost" contract and yields last within the block.
  (int, bool, bool) _queueYield(int take, int wanted) => (
    take >= wanted ? queue.length : (take - 1).clamp(0, queue.length),
    take > 0,
    take >= wanted,
  );

  _FramePlan _framePlanFor(int width, int height) {
    final inPrompt = prompt != null;
    final mandatory = _mandatoryChromeRows;
    // The scroll-progress indicator row ALWAYS paints — the percent rule
    // while the follow latch is detached, a blank row while following
    // (skipping it shifted every later row on scroll). Its row is the
    // `1 /* progress indicator */` inside [mandatory] — the busy row is
    // counted separately (`busy ? 1 : 0`).
    // Prompt mode (ask/approval): the prompt zone REPLACES the input zone
    // and its bottom rule, and paints its own spacer — the status row is
    // already inside `mandatory` (issue #479 AC4: the old budget charged
    // the prompt path for the input window, the never-painted bottom rule
    // AND the status row twice, so the frame under-filled and left a dead
    // band above the glass).
    final promptH = inPrompt ? tuiPromptRowCount(prompt!, width) + 1 : 0;
    final (inputVisible, inputOffset) = inPrompt
        ? (0, 0)
        : _visibleInputRows(mandatory, height);
    final fixed =
        mandatory -
        (inPrompt ? 1 : 0) /* the input zone's bottom rule never paints */ +
        (busy ? 1 : 0) +
        _menuReservedLines +
        promptH +
        inputVisible;
    final (
      subagentsWanted,
      boardWanted,
      waitingWanted,
      scheduledWanted,
      chipsWanted,
      queueWanted,
      stickyWanted,
    ) = _optionalSectionWants(
      width,
    );
    final optionalWanted =
        subagentsWanted +
        boardWanted +
        waitingWanted +
        scheduledWanted +
        chipsWanted +
        queueWanted +
        stickyWanted;
    var budget = (height - fixed).clamp(0, height);
    // Reserve a small live-edge tail (the sent echo lines + the newest
    // tool card) ONLY when the optional chrome would otherwise swallow the
    // whole viewport (squeezed frames): unsqueezed frames keep the exact
    // pre-#496 viewport so nothing else shifts. The reserve is a FLOOR —
    // the sections below consume from the remainder, never the reserve.
    final reserve = _liveEdgeReserve(optionalWanted, budget);
    var consumable = budget - reserve;
    int section(int wanted) {
      final take = wanted < consumable ? wanted : consumable;
      consumable -= take;
      return take;
    }

    final subagents = section(subagentsWanted);
    final board = section(boardWanted);
    final waiting = section(waitingWanted);
    final scheduled = section(scheduledWanted);
    final chips = section(chipsWanted);
    final queueTake = section(queueWanted);
    final (queueVisible, queueHeader, queueHint) = _queueYield(
      queueTake,
      queueWanted,
    );
    // The pinned echo is quantized all-or-nothing: a lone pin rule reads
    // as a glitch. When it does not fit, the row stays with history.
    // The taken rows LEAVE the consumable budget — history shrinks by
    // exactly what the echo paints, so the frame's total (sticky +
    // history + indicator + fixed) always equals the physical height and
    // the hard glass guard below never has to crop the echo away (the
    // #502 CI failure: sticky painted but history kept its unsqueezed
    // height, the 14-row frame overran a 12-row terminal and the guard
    // dropped rows from the TOP — the echo first).
    final historyNoSticky = consumable + reserve;
    var sticky = stickyWanted <= consumable ? stickyWanted : 0;
    // The wrap-turn dedupe (issue #917): pin only when the echo is above
    // the window THIS frame paints — the follow bottom, or the stored
    // offset detached — computed with the pin's own rows taken. The old
    // raw-[scrollOffset] check raced the painter: keystrokes re-wrap the
    // input zone between output events, the painted window moved while
    // the stored offset stood still, and the echo painted twice (pinned
    // AND re-scrolled into the window) or vanished unpinned. Deciding on
    // the painted geometry makes the dedupe exact — one paint wins under
    // any event interleaving — and needs no recursion: both candidate
    // heights are already in scope here.
    if (sticky > 0) {
      final endRow = _echoEndRow();
      // An empty wrap cache carries no geometry to dedupe against — the
      // transcript keeps the echo.
      if (endRow < 0) {
        sticky = 0;
      } else {
        final wrapped = _wrappedLines();
        final history = historyNoSticky - sticky;
        // The window top view() will paint, mirrored with THIS plan's
        // history — the real _scrollBottom reads _viewportHeight, which
        // is this very plan, so calling it here would recurse. Since
        // #1348 the follow anchor IS the live edge (the #827 turn-start
        // park is gone), so the only park above the bottom is the
        // boot-resume anchor carried in [scrollOffset].
        final bottom = history.clamp(0, wrapped.length);
        final paintedTop = followTail
            ? (scrollOffset > bottom ? scrollOffset : bottom)
            : scrollOffset.clamp(0, bottom);
        if (paintedTop < endRow) sticky = 0;
      }
    }
    consumable -= sticky;
    return _FramePlan(
      subagents: subagents,
      board: board,
      waiting: waiting,
      scheduled: scheduled,
      chips: chips,
      queue: queueVisible,
      queueHeader: queueHeader,
      queueHint: queueHint,
      sticky: sticky,
      history: consumable + reserve,
      input: inputVisible,
      inputOffset: inputOffset,
    );
  }

  /// The input zone's visible-row cursor window (issue #503): a
  /// paste-length draft yields rows — at least one row (the one the caret
  /// is on) always stays painted, never more than the chrome leaves room
  /// for. Returns the painted row count and the first painted row.
  (int, int) _visibleInputRows(int fixedChrome, int height) {
    // Issue #503: the input zone is a YIELDING section, not an unbounded
    // fixed one. A paste-length draft (many composer rows) used to blow
    // `fixed` past the physical height — the budget floored at 0, the
    // painted frame overran the glass, the terminal scrolled and the
    // composer row painted over the status row with the frame rules gone.
    final wanted = _inputLineCount;
    final cap = (height - fixedChrome - (busy ? 1 : 0)).clamp(
      1,
      height == 0 ? 1 : height,
    );
    final visible = wanted < cap ? wanted : cap;
    return (visible, _inputWindowOffset(visible));
  }

  /// The live-edge reserve for squeezed frames: [optionalWanted] chrome
  /// rows against a [budget]-row viewport. Zero while anything of the
  /// history fits (unsqueezed frames keep the exact pre-#496 viewport).
  int _liveEdgeReserve(int optionalWanted, int budget) {
    const liveEdgeRows = 4;
    if (optionalWanted < budget || budget <= 0) return 0;
    if (_wrappedLines().isEmpty) return 0;
    return liveEdgeRows > budget ? budget : liveEdgeRows;
  }

  /// The first visible wrapped-input row for a [visible]-row window: the
  /// caret's row stays the window's LAST row (bottom-anchored, like the
  /// history follow) so typing at the tail is always on the glass.
  int _inputWindowOffset(int visible) {
    final (_, cursorRow, _) = _wrappedInput();
    final total = _inputLineCount;
    if (visible >= total) return 0;
    return (cursorRow - visible + 1).clamp(0, total - visible);
  }

  int _viewportHeightFor(int width, int height) =>
      _framePlanFor(width, height).history;

  int get _viewportHeight => _viewportHeightFor(termWidth, termHeight);

  /// The sticky user echo pinned to the top while a run streams and the
  /// echo itself has scrolled out of view (Copilot-style, issue #496:
  /// paints only the plan's visible rows — yields whole when squeezed).
  int _writeStickyEcho(StringBuffer b, int visible) {
    // The pin-vs-transcript decision is the frame plan's ([_framePlanFor]):
    // [visible] (plan.sticky) is already zero when the transcript window
    // owns the echo.
    if (visible <= 0) return 0;
    final rows = _formattedStickyRows(termWidth);
    final count = visible < rows.length ? visible : rows.length;
    for (var i = 0; i < count; i++) {
      b.writeln(rows[i]);
    }
    return count;
  }

  /// The status row, fitted AND padded to the terminal width: a shorter new
  /// status (e.g. switching from a long model id to a short one) must
  /// overwrite the previous row's tail — the renderer only rewrites the
  /// cells the new content covers. Both operations are cell-width aware
  /// (grapheme clusters): UTF-16 padding underpads any status carrying wide
  /// characters and stale cells survive on the right.
  ///
  /// While the double-press Ctrl+C window is armed (issue #830), the dim
  /// `press ctrl+c again to exit` hint replaces the status line; the next
  /// keypress disarms and the status returns.
  String _statusRow() => ctrlCArmed
      ? _dim(tuiPadRight(kCtrlCExitHint, termWidth))
      : _dim(
          tuiPadRight(
            tuiFitWidth(callbacks.statusLine(), termWidth),
            termWidth,
          ),
        );

  /// The E1 belt: the engine's ladder is width-exact; a resize race
  /// truncates as the last resort so the row can never hardware-wrap.
  /// Pad after the cut — a truncated wide grapheme can leave the row
  /// short, and stale cells survive on the right of a short row.
  void _writeBeltRow(StringBuffer b, String raw) {
    b.writeln(_dim(tuiPadRight(tuiFitWidth(raw, termWidth), termWidth)));
  }

  /// One rendered span: the role style through the write-time seam, the
  /// band tint behind it unless the band is transparent.
  void _writeBandSpan(
    StringBuffer row,
    (String, StatusLineRoleKey) span,
    TuiTheme theme, {
    required bool idle,
    required double brandT,
    required RgbColor? bandBg,
  }) {
    final style = statusLineStyle(
      span.$2,
      theme: theme,
      idle: idle,
      brandT: brandT,
    );
    final c = FaThemeController.instance;
    row
      ..write(
        c.sgrPrefix(
          bandBg == null ? style : style.copyWith(backgroundRgb: bandBg),
        ),
      )
      ..write(span.$1);
  }

  /// The trailing gap: a transparent band resets and pads plain (the
  /// terminal background shows through); a filled band paints the bandBg
  /// fill flush to the right edge — either way the row stays full-width
  /// so stale cells die.
  void _writeBandGap(
    StringBuffer row,
    int pad,
    Style fill, {
    required bool transparent,
  }) {
    if (pad <= 0) return;
    final c = FaThemeController.instance;
    if (transparent) {
      // Reset first so the gap is plain terminal background.
      if (c.profile != null) row.write('\x1b[0m');
      row.write(' ' * pad);
    } else {
      row
        ..write(c.sgrPrefix(fill))
        ..write(' ' * pad);
    }
  }

  /// The status band row (#806): the omp band attachment — the host
  /// snapshot renders as a flush-left filled powerline band with a soft
  /// opening cap (nerd symbol table only; omp's font-safe table ships no
  /// cap), no frame, rules or corners. The band always owns its row (omp
  /// `verticalChrome: 1`) even when the engine has nothing to render.
  /// Colors flow through [statusLineStyle]/[kStatusLineRoles] at write
  /// time; width math runs on the raw strings (rule #279 E1).
  int _writeStatusBand(StringBuffer b) {
    final snapshot = callbacks.statusSnapshot!();
