/// `(sub: 'access', args: ['ask'])`; a bare `/skills` yields
/// `(sub: '', args: [])`).
({String sub, List<String> args}) splitSlashArgs(String rest) {
  final parts = rest
      .split(RegExp(r'\s+'))
      .where((part) => part.isNotEmpty)
