  'ghostty': ['GHOSTTY_RESOURCES_DIR'],
  'wezterm': ['WEZTERM_EXECUTABLE'],
  'windows-terminal': ['WT_SESSION'],
  'konsole': ['KONSOLE_VERSION'],
  'vte': ['VTE_VERSION'],
  'xterm': ['XTERM_VERSION'],
  'alacritty': ['ALACRITTY_LOG'],
