/// Slash-menu edit keys: backspace and typed characters keep editing the
/// input so `/models` can be typed in full. Command chords are ignored —
/// the decoder puts the BASE LETTER into `text` for control bytes
/// (ctrl+s → text 's'), and the catch-all insert below would otherwise
/// type that letter into the typed prefix exactly while the menu is open
/// (gh-1805: `/memory` picked after a Ctrl+S submit landed as `/smemory`).
/// Same guard as the other insert surfaces (_handleCharInsertKey,
/// _pickerTypeFilter); shift is deliberately not blocked so shifted
/// letters still type.
(Model, Cmd?) _handleSlashMenuEditKey(KeyMsg msg) {
  switch (msg.key) {
    case 'backspace':
      if (cursor > 0 && inputText.isNotEmpty) {
        return (
          _updateMenuForInput(copyWith(editor: editor.backspace())),
          null,
        );
      }
      return (this, null);
    default:
      if (FaTuiModel._isCommandKeystroke(msg.key)) return (this, null);
      final text = msg.keyEvent.text;
      if (text.isNotEmpty && text.length == 1) {
        return (
          _updateMenuForInput(copyWith(editor: editor.insert(text))),
          null,
        );
      }
      return (this, null);
  }
}

/// A single key press from an interactive terminal in raw mode.
///
/// Either [char] is set for a printable character, or [type] identifies a
/// special key. Modifiers are reported when the terminal sends them.
final class KeyEvent {
  const KeyEvent({
    this.char,
    required this.type,
    this.shift = false,
    this.ctrl = false,
    this.alt = false,
  });

  /// Printable character, if any. Null for special keys.
  final String? char;

  /// The key type.
  final KeyType type;

  /// Whether Shift was held.
  final bool shift;

  /// Whether Ctrl was held.
  final bool ctrl;

  /// Whether Alt/Meta was held.
  final bool alt;

  @override
  String toString() =>
      'KeyEvent(char: $char, type: $type, shift: $shift, ctrl: $ctrl, alt: $alt)';
}

